  function hwpxText(node){return [...node.getElementsByTagName('*')].filter(element=>element.localName==='t').map(element=>element.textContent||'').join('').replace(/\s+/g,' ').trim();}
  function hwpxHasAncestor(node,name){for(let parent=node.parentElement;parent;parent=parent.parentElement)if(parent.localName===name)return true;return false;}
  function parseMajorDate(text,defaultYear){
    const normalized=String(text||'').replace(/[()（）][월화수목금토일][요일]*[)）]/g,' ').trim();
    let match=normalized.match(/(20\d{2})\s*[.\/-년]\s*(\d{1,2})\s*[.\/-월]\s*(\d{1,2})\s*일?/);
    if(!match)match=normalized.match(/(?:^|\s)(\d{1,2})\s*[.\/-월]\s*(\d{1,2})\s*일?/);
    const year=match?(match.length===4?Number(match[1]):defaultYear):0,month=match?Number(match[match.length-2]):0,day=match?Number(match[match.length-1]):0,date=new Date(year,month-1,day);
    return match&&date.getFullYear()===year&&date.getMonth()===month-1&&date.getDate()===day?{date:dateKey(date),matched:match[0].trim()}:null;
  }
  async function parseMajorHwpx(file){
    if(typeof JSZip==='undefined')throw new Error('HWPX 처리 모듈을 불러오지 못했습니다. 인터넷 연결 후 다시 시도해주세요.');
    const zip=await JSZip.loadAsync(await file.arrayBuffer()),names=Object.keys(zip.files).filter(name=>/^Contents\/section\d+\.xml$/i.test(name)).sort(),raw=[];
    if(!names.length)throw new Error('올바른 HWPX 문서가 아닙니다.');
    for(const name of names){
      const xml=new DOMParser().parseFromString(await zip.file(name).async('string'),'application/xml'),elements=[...xml.getElementsByTagName('*')],tables=elements.filter(element=>element.localName==='tbl');
      tables.forEach(table=>elements.filter(element=>element.localName==='tr'&&hwpxHasAncestor(element,'tbl')&&table.contains(element)).forEach(row=>{const cells=elements.filter(element=>element.localName==='tc'&&row.contains(element)&&!elements.some(other=>other!==element&&other.localName==='tc'&&row.contains(other)&&other.contains(element))).map(hwpxText).filter(Boolean);if(cells.length)raw.push(cells);}));
      elements.filter(element=>element.localName==='p'&&!hwpxHasAncestor(element,'tbl')).forEach(paragraph=>{const text=hwpxText(paragraph);if(text)raw.push([text]);});
    }
    const allText=raw.flat().join(' '),fileYear=String(file.name).match(/20\d{2}/)?.[0],contentYear=allText.match(/20\d{2}/)?.[0],defaultYear=Number(fileYear||contentYear||new Date().getFullYear()),events=[];
    raw.forEach(cells=>{const dated=cells.map(cell=>({cell,parsed:parseMajorDate(cell,defaultYear)})).filter(item=>item.parsed);dated.forEach(({cell,parsed})=>{let title=dated.length>1?cell.replace(parsed.matched,'').replace(/^[\s:：·~-]+/,'').trim():cells.filter(value=>value!==cell).join(' · ').replace(/^(주요\s*)?(일정|내용|교육활동|행사명)\s*[:：]?\s*/,'').trim();if(!title)title=cell.replace(parsed.matched,'').replace(/^[\s:：·~-]+/,'').trim();if(!title||/^(날짜|일자|요일|계|비고)$/.test(title))return;events.push({date:parsed.date,title});});});
    return events.filter((item,index,all)=>all.findIndex(other=>other.date===item.date&&other.title===item.title)===index).sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title,'ko'));
  }
