    el.innerHTML=`${dateNav('reservations')}<div class="dashboard-res-toolbar"><div class="dashboard-res-tabs"><button class="${D.reservationView==='special'?'active':''}" onclick="dashboardSetReservationView('special')">특별실</button><button class="${D.reservationView==='classroom'?'active':''}" onclick="dashboardSetReservationView('classroom')">교실 예약</button></div><button class="dash-primary" onclick="dashboardOpenReservation()"><i class="fas fa-plus"></i> 바로 예약</button></div><div class="dashboard-res-legend">초록: 정규수업 · 노랑: 예약 · 빈칸을 누르면 바로 예약 <strong style="margin-left:6px;color:#111;font-size:9px">* 교실담당자와 반드시 협의</strong></div><div class="reservation-wrap">${tables}</div>`;
