  function cleanMealItems(value){return String(value||'').split('<br/>').map(x=>x.replace(/\s*\([^)]*\)\s*/g,'').replace(/[0-9.]+/g,'').replace(/-\s*$/,'').trim()).filter(Boolean);}
  async function renderMeal(force=false){const el=$('dash-meal');if(!el)return;const key=dateKey(dateFor('meal')).replaceAll('-','');const cacheKey=`neisMeal:v2:${key}`;if(!force){try{const c=JSON.parse(localStorage.getItem(cacheKey)||'null');if(c&&Date.now()-c.savedAt<21600000){mealHtml(el,c.meals);return;}}catch(e){}}el.innerHTML=dateNav('meal')+'<div class="dash-loading">급식 정보를 불러오는 중…</div>';try{const url=`https://open.neis.go.kr/hub/mealServiceDietInfo?Type=json&pIndex=1&pSize=10&ATPT_OFCDC_SC_CODE=${NEIS.office}&SD_SCHUL_CODE=${NEIS.school}&MLSV_YMD=${key}`;const response=await fetch(url);if(!response.ok)throw new Error('http');const json=await response.json();const rows=json?.mealServiceDietInfo?.[1]?.row||[];const meals={lunch:[],dinner:[]};rows.forEach(row=>{const code=String(row.MMEAL_SC_CODE||''),name=String(row.MMEAL_SC_NM||'');if(code==='3'||name.includes('석식'))meals.dinner=cleanMealItems(row.DDISH_NM);else if(code==='2'||name.includes('중식'))meals.lunch=cleanMealItems(row.DDISH_NM);});localStorage.setItem(cacheKey,JSON.stringify({savedAt:Date.now(),meals}));if(dateKey(dateFor('meal')).replaceAll('-','')===key)mealHtml(el,meals);}catch(e){if(dateKey(dateFor('meal')).replaceAll('-','')===key)el.innerHTML=dateNav('meal')+'<div class="dash-empty">오늘 급식 정보를 불러오지 못했습니다.</div>';}}
  function mealHtml(el,meals){const hasLunch=meals?.lunch?.length,hasDinner=meals?.dinner?.length;if(!hasLunch&&!hasDinner){el.innerHTML=dateNav('meal')+'<div class="dash-empty">오늘은 등록된 급식이 없습니다.</div>';return;}const sections=[['중식',meals.lunch],['석식',meals.dinner]];el.innerHTML=dateNav('meal')+`<div class="dashboard-meal-sections">${sections.map(([title,items])=>`<section class="dashboard-meal"><h4>${title}</h4>${items?.length?items.map(esc).join('<br>'):`<span class="dashboard-meal-empty">${title} 메뉴가 등록되지 않았습니다.</span>`}</section>`).join('')}<small class="dashboard-meal-note">알레르기 번호는 간략 화면에서 제외했습니다.</small></div>`;}
