  function item(n,title,content,type,meta){const replies=values(n.replies).sort((a,b)=>(a.createdAt||0)-(b.createdAt||0)),canReply=PROTECTED_TYPES.has(type),collapsible=['notices','memos','meetings'].includes(type),collapsed=collapsible&&itemCollapsed(type,n.id),replyHtml=replies.length?`<div class="dash-replies">${replies.slice(-2).map(reply=>`<div class="dash-reply"><i class="fas fa-reply"></i><div><span>${esc(reply.content)}</span><small>${esc(reply.author||'교직원')} · ${fmtTime(reply.createdAt)}</small><div class="dash-reply-actions"><button onclick="dashboardEditReply('${type}','${n.id}','${reply.id}')">수정</button><button onclick="dashboardDeleteReply('${type}','${n.id}','${reply.id}')">삭제</button></div></div></div>`).join('')}${replies.length>2?`<div class="dash-reply-more">이전 답글 ${replies.length-2}개</div>`:''}</div>`:'';return `<div class="dash-item ${collapsed?'is-item-collapsed':''}"><div class="dash-item-heading"><div class="dash-item-title">${title}</div>${collapsible?`<button class="dash-item-toggle" onclick="dashboardToggleItem('${type}','${n.id}')" aria-label="${collapsed?'펼치기':'접기'}"><i class="fas fa-chevron-${collapsed?'down':'up'}"></i></button>`:''}</div><div class="dash-item-details">${content?`<div class="dash-item-content">${esc(content).slice(0,180)}</div>`:''}<div class="dash-item-meta">${meta}</div>${replyHtml}<div class="dash-row-actions"><button onclick="dashboardEdit('${type}','${n.id}')">수정</button><button onclick="dashboardDelete('${type}','${n.id}')">삭제</button>${canReply?`<button class="dash-reply-btn" onclick="dashboardReply('${type}','${n.id}')"><i class="fas fa-reply"></i> 답글</button>`:''}</div></div></div>`;}

  window.dashboardMoveDate=(id,n)=>{const date=dateFor(id);date.setDate(date.getDate()+Number(n));renderSection(id);};
